from math import sqrt
import sys

def intersect_circle(circle1, circle2):
    d = sqrt((circle1[0] - circle2[0])**2 + (circle1[1] - circle2[1])**2)
    diff = abs(circle2[2] - circle1[2])
    return d > diff

def expand_circle(circle, distance, new_circle):
    if intersect_circle(circle, new_circle):
        return min(distance, abs(circle[2] - new_circle[2]))
    else:
        return sqrt(abs(circle[2]**2 - distance**2)**0.5 + 1) + circle[2]

def flood_fill(circle_list, circle):
    count = 0
    visited = set()
    queue = [circle]
    while queue:
        relief = False
        for _ in range(len(queue)):
            rng = []
            for x, y, r in queue:
                if (x, y) not in visited:
                    visited.add((x, y))
                    for i in range(r):
                        if (x + i, y + i) not in visited and 0 <= x + i < 10**4 and 0 <= y + i < 10**4:
                            if intersect_circle(circle, (x + i, y + i, r)):
                                rng.append((x + i, y + i, r))
                                count += 1
                                relief = True
            if not relief:
                for x, y, r in rng:
                    visited.remove((x, y))
                    queue.remove((x, y, r))
    return count

def update_rcp(points, inter):
    rcp, count = -1, 0
    for point in inter:
        if len(point) > rcp:
            rcp, count = point[2], len(point)
    if count == len(points):
        return float(inf)
    for point in points:
        count -= flood_fill(pls, point)
    return rcp if count else float(inf)

def solution(radius):
    pls = [(x, y, abs(radius - sqrt(x**2 + y**2))) for x, y in points]
    intcs = [(x, y, 0) for x, y in points]
    points += intcs
    rcp = float(inf)
    rcp = update_rcp(points[:1], intcs)  # For the circle without any other points, the border is of radius 0 circle.
    if rcp == float(inf):
        return -1
    else:
        return min(abs(radius), rcp)
