from math import gcd
from functools import reduce
from itertools import groupby

def lcm(x, y):
    return x * y // gcd(x, y)

def sum_madnesses(n, m, p):
    used = [[0 for _ in range(-1000, 1001)] for _ in range(n)]
    unique_b = ['L'] + ['R'] * 2**(m-1)
    total_madnesses = 0
    mod_partitions = [set([1])]
    prime = 10**8 % p

    for i, b in enumerate(unique_b):
        current_madnesses = 0
        for members in groupby(range(m), key=lambda x: members[reversed(b)][x - 1]):
            for member, _ in members:
                current_madnesses += reduce(lcm, [event[1] for event in groupby(used[member][i], key=lambda y: n - y) if y != 1])
        if current_madnesses % prime:
            mod_partitions = set()
            effective_mod = 0
        for partition in mod_partitions:
            mod_partitions.add(hamkins_permutation(current_madnesses - partition, i + 1))
            effective_mod += current_madnesses - partition
        total_madnesses = (total_madnesses + effective_mod) % p

    return total_madnesses

def hamkins_permutation(current_madnesses, position):
    base_madness = 2 * (4 - max(0, current_madnesses // 2)) - position
    if current_madnesses < base_madness + 2:
        base_madness += 2
    return base_madness

