from operator import itemgetter

def split_sequence(sequence, prefix):
    for i, char in enumerate(sequence):
        if char == prefix[i]:
            yield prefix[:i+1], i

def is_sequence_increasing(sequence):
    return all(sequence[i] < sequence[i+1] for i in range(len(sequence) - 1))

def is_sequence_decreasing(sequence):
    return all(sequence[i] > sequence[i+1] for i in range(len(sequence) - 1))

def find_sequences(sequence):
    prefixes = [("", i) for i in range(len(sequence) + 1)]
    for size in range(1, len(sequence) + 1):
        for i in range(len(sequence) - size + 1):
            prefix, index = prefixes[i]
            for next_prefix, j in split_sequence(sequence[i+1:], prefix + sequence[i+1:]):
                prefixes[j] = next_prefix

    result = []
    for prefix in prefixes[len(sequence):]:
        increasing, decreasing = prefix[:], prefix[:]
        increasing[-1] = decreasing[-1] = "-1"
        for i in range(1, len(increasing)):
            if is_sequence_increasing(increasing[:i]) and is_sequence_decreasing(decreasing[:i]):
                result.append(increasing[:i] + decreasing[i:])
                break

    return list(filter(None, result))

def main():
    lines = sys.stdin.readlines()
    sequence = list(map(int, list(lines[1].strip().split(" "))))
    if len(sequence) == 1:
        print("YES", "0")
