    current_prefix_sum = 0
    should_increase = False
    for i, num in enumerate(sequence):
        should_increase = should_increase or (num > 0 and current_prefix_sum < 0 or num == 0 and current_prefix_sum == 0)

        if num > 0:
            if should_increase:
                increasing.append(num)
            else:
                if decreasing or should_increase:
                    decreasing.append(num)
                else:
                    increasing.append(-num)
        else:
            if should_increase:
                increasing.append(-num)
            else:
                if decreasing or should_increase:
                    decreasing.append(num)
                else:
                    increasing.append(0)

        if i > 0:
            current_prefix_sum += increasing[-1] + decreasing[-1]

        if len(increasing) == len(decreasing) and should_increase:
            return

    result_sequences = find_sequences(increasing + decreasing)
    if not result_sequences:
