def calculate_sum(robots, directions, prime):
    mod = 10**9 + 7
    power_mod = [1, 10**9 + 7]
    for i in range(2, len(directions) + 1):
        power_mod.append(power_mod[i - 1] * power_mod[1] % mod)

    dp = [[pow(2, k, mod) for k in range(robots + 1)] for row in range(len(directions) + 2)]
    dp[0][0] = 1

    for robot in range(robots):
        for direction in range(1, len(directions) + 1):
            for limit in range(1, robots + 1):
                if directions[robot] == 'L' and direction < limit:
                    continue
                dp[limit][direction] = (dp[limit][direction] + dp[robot + 1][direction - limit]) % mod

    res = [0] * (len(dp[-1]) - 1)
    for robot in range(robots):
        for direction in range(1, len(directions) + 1):
            total = mod
            if robot > 0 and directions[robot] == 'L' and robot - robot > limit[robot]:
                total = (total - dp[robot][direction] * (directions[robot] == 'L')) % mod
            res[robot] = (res[robot] + total * power_mod[direction]) % mod

    return sum(res) % prime

