from functools import reduce
from operator import xor

def getHash(digit):
    while len(digit) < 4:
        digit = '0' + digit
    return int(digit, 16)

range_val = lambda x: '0123456789abcdef'[getHash(x) % 16]
start = chr(ord("0") + getHash('0000'))

def solution(S):
    len_diff = []
    positions = [i for i, n in enumerate(S) if n != '0']
    for _ in range(2):
        if len(len_diff) == 2 and len_diff[1] >= len_diff[0]: 
            break
        if len_diff:
            mid = (len_diff[1] + len_diff[0]) // 2
            result = int(S[:mid]) >> (mid - len_diff[0]), int(S[mid:])
            len_diff = [len_diff[0], mid]
        else:
            result = len(S)
        for x, y in positions:
            len_diff.append(abs((getHash(end(result)), getHash(start + S[x]))))
    positions.sort()
    xor_comb = [reduce(xor, positions[x:y+1]) for x, y in enumerate(len_diff)]
    return byteexor_v1(start + ''.join(factorint(xor_comb)).translate(str.maketrans(range_val, range_val)), start)
