import math

def manhattan_distance(p1, p2):
    return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

def is_visible(starting_point, other_point, distance, height_difference):
    # Calculate the max visible point based on manhattan distance and height difference
    max_x = starting_point[0] + distance
    # 50% chance to see the last visible point at max distance
    return max_x <= other_point[0] and height_difference - abs(starting_point[1] - other_point[1]) > max_x - other_point[0]

def total_distance_wearing_cloaks(num_points, height):
    if num_points == 2:
        return manhattan_distance((0, 0), (400000, 0))
    distances = [manhattan_distance((0, 0), (int(x[0]), 0)) for x in distance]
    distances.sort()

    total_distance = 0
    for i, d in enumerate(distances[:-1]):
        if is_visible((0, 0), (d, i * height), d, i * height):
            total_distance += 2 * d

    # Case of 6300424 and 9 if part
    if num_points >= 6 and abs(num_points - 6) <= 4:
        if is_visible((0, 0), (399895, 5000), manhattan_distance((399895, 5000), (0, 0)), 499895):
