from math import gcd
from collections import namedtuple

def lcm(a, b):
    def extended_gcd(a, b):
        if a == 0:
            return (b, 0, 1)
        g, y, x = extended_gcd(b % a, a)
        return (g, x - (b // a) * y, y)

    if b == 0:
        return a
    if a == 0:
        return 0

    g, u, v = extended_gcd(a, b)
    return (g * (a // g) * (b // g), u * (a // g), v * (b // g))

def next_multiple(n, k):
    return n + sum(k // lcm(n, d) for d in divisors)

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > i:
        factors.append(n)
    return factors

def divisors(n):
    if n < 2:
        return set()
    divisors = set()
    divisors.add(1)
    divisors.add(n)
    factors = prime_factors(n)
    for factor in factors:
        divisors.add(factor)
        if factor * factor <= n:
            divisors.add(factor * factor)
        while n % factor == 0:
            divisors.add(factor)
            n //= factor
    if n > 1:
        divisors.add(n)
    return divisors

