from math import gcd
from collections import defaultdict

def polar_decomposition(n, triplets):
    groups = defaultdict(set)
    for a, b, t in triplets:
        if a == 1:
            groups[n].add(b)
        for i in range(1, n):
            d = gcd(a, i)
            temp = n
            while d > 0:
                if temp // d == (a // d) ** 2:
                    temp = temp // d**2
                    groups[i].add(b)
                else:
                    break
                d = gcd(d, temp // d)
    return groups

def find(x, groups):
    while x != groups[x]:
        x = groups[x]
    return x

def uni_pairs(A):
    P = [0] + sorted(A)
    groups = {}

    def join(x, y):
        if (x,y) in groups or (y,x) in groups:
            return

        p1, p2 = find(x, groups), find(y, groups)
        if p1 < p2:
            groups[p2] = (p1, p2)
        else:
            groups[p1] = (p1, p2)

    joined = set()
    for i, a in enumerate(P[:-1], 1):
        for j, b in enumerate(P[i:]):
            if i != j:
                join(a ** i, b ** j)
                joined.add(a ** i)

    for g in groups.values():
        if g[1] in joined:
            yield g

