from collections import Counter, deque
from heapq import heapify, heappush, heappop

def solve(num_logs, lengths):
    # Create a counter of log lengths
    log_counts = Counter(lengths)
    # Create a min heap of the longest logs first
    log_heap = sorted(log_counts.keys())
    heapify(log_heap)

    # If there are more than two logs of the same length, choose the one with the largest remaining size
    while len(log_counts) > 2:
        log_large = heappop(log_heap)
        if log_large - 1 in log_counts:
            log_counts[log_large - 1] += 1
            heappush(log_heap, log_large - 1)
        if log_large - 2 in log_counts:
            log_counts[log_large - 2] += 1
            heappush(log_heap, log_large - 2)

        if len(log_counts) > 2:
            log_large = heappop(log_heap)
            if log_large - 1 in log_counts:
                log_counts[log_large - 1] += 1
                heappush(log_heap, log_large - 1)
            if log_large - 2 in log_counts:
                log_counts[log_large - 2] += 1
                heappush(log_heap, log_large - 2)

    max_raft_area = 0
    # Try all pairs of lengths (x, y) for max possible area
    pairs = [(a, 2) for a in log_counts.keys()] + [(2, b) for b in log_counts.keys()]
    pairs.sort(reverse=True)
    for (x, y) in pairs:
        n_x = log_counts[x]
        n_y = log_counts[y]
        total_length = 2 * x + y * n_x + 2 * y * n_y
        max_area = total_length // 4
        for i in range(n_x):
            for j in range(n_y):
                if (x - 2) * (y - 2) < max_area:
                    break
                if x == y and (x - 2) * (y - 2) < max_area:
                    break
                if x > y and (x - 1) * (y - 2) <= max_area:
                    break
                max_area = max(max_area, ((x - 2) * (y - 2)), ((x - 1) * (y - 1)), (x * (y - 1)))
        if max_area < 2:
            break

    return max_area

if __name__ == "__main__":
    while True:
        try:
            n_logs = int(input())
            lengths = list(map(int, input().split()))
            print(solve(n_logs, lengths))
        except:
            break
