from collections import *

def parse_input():
    n = int(input().strip())
    seq = list(map(int, input().strip().split()))
    return n, seq

def find_possible_starts(seq):
    log_seq = sorted(set(seq))
    n = len(log_seq)

    # Find starting indices for increasing and decreasing sequences
    increasing_starts = [log_seq[i] for i in range(n) if seq[([log_seq[j] for j in range(i)] + [log_seq[i]])[:n - i]] < log_seq[i]]
    decreasing_starts = [log_seq[i] for i in range(n) if seq[([log_seq[j] for j in range(i)] + [log_seq[i]])[:n - i]] > log_seq[i]]

    if len(increasing_starts) != len(decreasing_starts):
        return None, None
    else:
        return increasing_starts, decreasing_starts

def is_valid(a, seqs):
    # Check if the sequence is sorted in increasing order
    if any(s for i in range(len(a) - 1) for s in (a[i:] + a[:i]) if [seqs[1][1][j] for j in range(i)] < seqs[0][1][:len(a) - (i + 1)] if a[i + j] in seqs[0][0]):
        return False

    # Check if the sequence repeats patterns
    if any(tuple(sorted((a[i+1:i+3], a[i+2:i+3]))) in [(seqs[1][1][j:j+3], seqs[0][1][j:j+3]) for i in range(0, len(a) - 2)]:
        return False

    return True

def solve(n, seq):
    seqs = [['', 0], ['', n + 1]]  # Increase and decrement patterns

    increasing_starts, decreasing_starts = find_possible_starts(seq)

    if not increasing_starts or not decreasing_starts:
        return "NO"

    for start in decreasing_starts:
        start += 1
        valid = is_valid(seq, [(seqs[1][1][j:j+start], seqs[0][1][j:j+start]) for j in range(len(seq) - start)])
        if valid:
            seqs[0][1] -= start
            seqs[1][1] += start
            break

    else:
        for start in increasing_starts:
            valid = is_valid(seq, [(seqs[1][1][j:j+start], seqs[0][1][j:j+start]) for j in range(len(seq) - start)])
            if valid:
                seqs[0][1] += start
                seqs[1][1] -= start
                break

        else:
            return "NO"

    return "YES\n" + " ".join(map(str,(len(seqs[0][1]), seqs[0][1])))
