To solve this problem, we can implement a dynamic programming approach to calculate the GCD of subsequences of increasing lengths. We will create a DP table where `dp[i][j]` represents the maximum GCD of a subsequence of length `i` from the array that includes at most `j` different numbers.

Here's how the Python program to solve this problem could look like:

```python
from math import gcd
from collections import defaultdict

def can_hieve(arr):
    n = len(arr)
    dp = [[0] * n for _ in range(n)]

    # Initialize base cases
    for i in range(n):
        dp[i][i] = arr[i]
        if gcd(arr[i], arr[i]) > 1:
            return "NO"
        else:
            dp[i][i] = 1

    # Fill the DP table
    for sublen in range(2, n + 1):  # Subsequence length
        for start in range(n - sublen + 1):
            end = start + sublen - 1
            prev = defaultdict(lambda: -10**10)
            for i in range(start, end + 1):
                g = gcd(dp[start][i - 1], arr[i])
                dp[start][i] = max(dp[start][i], g)
                if g > 1:
                    prev[g] = dp[start][i]
                if prev[g] > 1:
                    dp[start][i] = max(dp[start][i], prev[g])

    # Check for any number with higher GCD than 2
    for i in range(n):
        for j in range(n):
            if gcd(arr[i], arr[j]) > 1 and dp[i][j] > 1:
                return "NO"
            elif i > j:
                return "NO"

    return "YES"

