def k_lucky_ticket(k):
    """Generate k-lucky tickets up to length 8."""
    digits = [i for i in range(k + 1)]
    tickets = set()
    for length in range(1, min(8, len(str(k))) + 1):
        for comb in itertools.combinations(digits, length):
            comb_str = ''.join(map(str, comb))
            for i in range(1, len(comb_str) + 1):
                for op in ['+', '-']:
                    # Combine combinations with the two digits on either end
                    tickets.add(f"{comb_str[0]}{comb_str[1:i+2]}{op}{comb_str[-i]}{comb_str[-1]}")
                    # Combine combinations with the variable first digit
                    tickets.add(f"{comb_str[0]}{comb_str[1:i+2]}{comb_str[-i]}{comb_str[-1]}")
                    for j in range(1, len(comb_str), 2):
                        tickets.add(f"{comb_str[0]}{comb_str[1:j+1]}{comb_str[j+1:i-1]}{op}{comb_str[i-1]}{comb_str[j]}{comb_str[i+1]}{comb_str[-i]}")
                        tickets.add(f"{comb_str[0]}{comb_str[1:j+1]}{comb_str[j+1:i-1]}{comb_str[i-1]}{comb_str[j]}{comb_str[i+1]}{comb_str[-1]}")
    return tickets

