def smallest_permuted_difference(element):
    max_digits = []
    for e in ['a', 'b', 'c', 'd', 'e', 'f']:
        for i in range(2, 16):
            if len(element) > (hex(i).replace('0x', '').zfill(2) * (i - 1)).find(e) + 2:
                max_digits.append(True)
            else:
                max_digits.append(False)
    if sum(max_digits) == 6:
        return element
    elif sum([i for i in max_digits if 'a' in i or 'b' in i or 'c' in i or 'd' in i or 'e' in i or 'f' in i]) == 6:
        return '00' + element[2 - 1 - element.find('a')]
    elif max_digits.count(True) == 2:
        return element[:2][:2] * 2
    return 'NO'


def solve(S):
    S = chr(16 - bin(int(S, 16))[3:].count('1')) + oct(int(S, 16))[3:]
    return smallest_permuted_difference(S)


if __name__ == '__main__':
