def find_arithmetic_progressions(n, sequence):
    progressions = 1  # Start with at least one progression containing all illegal values (-1)
    illegal_count = 0  # Zero illegal values have their own progression

    # Count illegal values
    for value in sequence:
        if value == -1:
            illegal_count += 1

    if illegal_count == 0:
        return 1  # If no illegal values, just one progression
    elif illegal_count == n:
        return 2  # If all values are illegal, two progressions covering all

    for i in range(1, n):
        if sequence[i] - sequence[i - 1] == 1:
            progressions += 1
        elif sequence[i - 1] - sequence[0] == 2:
            progressions += 1
        else:
            progressions += 1

    return progressions

