def is_strong(cactus, added_edges):
    """
    Check if the graph formed by adding the added_edges is a strong cactus.
    """
    connections = {}
    for u, v in added_edges:
        connections[(u, v)] = connections[v, u] = True

    def is_connected(u, v, visited, order):
        order.append(u)
        visited[u] = True
        for neighbor, to_add in connections.items():
            if neighbor[0] == u and not visited[neighbor[1]] and not to_add:
                is_connected(neighbor[1], v, visited, order)
            if neighbor[1] == u and not visited[neighbor[0]] and not to_add:
                is_connected(neighbor[0], v, visited, order)
        order.append(v)

    groups = []
    visited = [False] * (len(cactus) + 1)
    for u in range(1, len(cactus) + 1):
        if not visited[u]:
            order = []
            is_connected(u, 0, visited, order)
            groups.append(order)

    return len(groups) != len(set(groups))

