def topological_sort(graph):
    sorted_nodes = []
    stack = []
    visited = set()
    for node in graph:
        if (node not in visited and len(graph[node]) == 0):
            heappush(stack, -node)
    while stack:
        node = heappop(stack)
        sorted_nodes.append(-node)
        visited.add(node)
        for neighbor in graph[node]:
