from collections import defaultdict

def min_arithmetic_progressions(n, a):
    dp = [-1] * (n + 1)
    result = float('inf')

    for i in range(n):
        if a[i] != -1:
            c1 = a[i]
            seen = 1
        else:
            c1 = None
            seen = 0

        for j in range(i + 1, n + 1):
            if a[j] != -1:
                c2 = a[j]
            else:
                c2 = None

            if c1 is None or c2 is None or c1 == c2:
                d = j - i
                for k in range(i, j + 1):
                    dp[k] = d

            else:
                d = j - i
                for k in range(i, j):
                    if dp[k] > d:
                        dp[k] = d

            if seen + d < result:
                result = seen + d

    return result

n = int(input().strip())
