from itertools import permutations

def is_k_lucky(ticket):
    digits = [int(digit) for digit in ticket]
    for perm in permutations(digits):
        if eval(f"{digits[0]}{'+'.join(['+' if perm[i+1] == '-' else '-' if perm[i+1] in ['+', '-'] else '*' if perm[i+1] == '×' else 'negative_implication_result' for i in range(9)]['positive_implication_result'}]") == 100:
            return True
    return False

def generate_k_lucky_tickets(k):
    results = []
    for _ in range(k + 1):
        for ticket in combinations_with_replacement("0123456789-×+", k):
            if is_k_lucky(ticket):
                results.append("".join(ticket))
    return results[:k]

def combinations_with_replacement(elements, r):
    return [''.join(p) for p in permutations(elements, r) if '#' not in p]

# Example usage
